Here are examples demonstrating how to use `useRef` in React with a `string`, an `array`, and an `object`:

### 1. **Using `useRef` with a String:**

```typescript
import React, { useRef } from 'react';

function StringRefComponent() {
  // Create a reference for a string
  const stringRef = useRef<string>('Initial Value');

  const updateString = () => {
    // Update the ref value
    stringRef.current = 'Updated Value';
    console.log('Current String Ref:', stringRef.current);
  };

  return (
    <div>
      <p>String Ref: {stringRef.current}</p>
      <button onClick={updateString}>Update String Ref</button>
    </div>
  );
}

export default StringRefComponent;
```

### 2. **Using `useRef` with an Array:**

```typescript
import React, { useRef } from 'react';

function ArrayRefComponent() {
  // Create a reference for an array
  const arrayRef = useRef<number[]>([1, 2, 3]);

  const updateArray = () => {
    // Push a new value to the array
    arrayRef.current.push(4);
    console.log('Current Array Ref:', arrayRef.current);
  };

  return (
    <div>
      <p>Array Ref: {arrayRef.current.join(', ')}</p>
      <button onClick={updateArray}>Update Array Ref</button>
    </div>
  );
}

export default ArrayRefComponent;
```

### 3. **Using `useRef` with an Object:**

```typescript
import React, { useRef } from 'react';

function ObjectRefComponent() {
  // Create a reference for an object
  const objectRef = useRef<{ name: string; age: number }>({
    name: 'John',
    age: 30,
  });

  const updateObject = () => {
    // Update object ref values
    objectRef.current.name = 'Jane';
    objectRef.current.age = 25;
    console.log('Current Object Ref:', objectRef.current);
  };

  return (
    <div>
      <p>Name: {objectRef.current.name}</p>
      <p>Age: {objectRef.current.age}</p>
      <button onClick={updateObject}>Update Object Ref</button>
    </div>
  );
}

export default ObjectRefComponent;
```

### Explanation:
- **`useRef`** is used to create a mutable object that persists across renders.
- It doesn't cause a re-render when updated, so changes to `.current` will not trigger a re-render, but the new values can still be accessed in the event handlers.

