import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

public class PartitionByPredicate {

    /**
     * Partitions a list of integers into even and odd numbers.
     *
     * @param numbers the list of integers
     * @return a map with two entries: one for even numbers and one for odd numbers
     */
    public Map<Boolean, List<Integer>> partitionByEvenOdd(List<Integer> numbers) {
        return numbers.stream()
                      .collect(Collectors.partitioningBy(n -> n % 2 == 0));
    }

    public static void main(String[] args) {
