public class ReverseString {
    public static void main(String[] args) {
        String input = "chatgpt5";
        char[] arr = input.toCharArray();

        int left = 0, right = arr.length - 1;

        while (left < right) {
            char temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;

            left++;
            right--;
        }

