Here are **industry-level ways** to find all permutations of a string 👇

---

### 1. Backtracking (Most Important 🔥)

```java id="pm1k9x"
import java.util.*;

public class Permutations {

    public static void main(String[] args) {
        String str = "abc";
        List<String> result = new ArrayList<>();

        permute(str.toCharArray(), 0, result);
        System.out.println(result);
    }

    static void permute(char[] arr, int index, List<String> result) {
        if (index == arr.length) {
            result.add(new String(arr));
            return;
        }

        for (int i = index; i < arr.length; i++) {
            swap(arr, index, i);
            permute(arr, index + 1, result);
            swap(arr, index, i); // backtrack
        }
    }

    static void swap(char[] arr, int i, int j) {
        char temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
```

---

### 2. Using Recursion (Substring approach)

```java id="pm2p7m"
import java.util.*;

public class Permutations {

    public static void main(String[] args) {
        String str = "abc";
        List<String> result = new ArrayList<>();

        permute("", str, result);
        System.out.println(result);
    }

    static void permute(String prefix, String remaining, List<String> result) {
        if (remaining.length() == 0) {
            result.add(prefix);
            return;
        }

        for (int i = 0; i < remaining.length(); i++) {
            permute(prefix + remaining.charAt(i),
                    remaining.substring(0, i) + remaining.substring(i + 1),
                    result);
        }
    }
}
