### 2. QuickSelect (Best - O(n) avg 🔥🔥)

```java id="kl2p7m"
import java.util.*;

public class KthLargest {

    public static void main(String[] args) {
        int[] arr = {3,2,1,5,6,4};
        int k = 2;

        int result = quickSelect(arr, 0, arr.length - 1, arr.length - k);
        System.out.println(result);
    }

    static int quickSelect(int[] arr, int l, int r, int k) {
        if (l == r) return arr[l];

        int pivot = partition(arr, l, r);

        if (pivot == k) return arr[pivot];
        else if (pivot < k) return quickSelect(arr, pivot + 1, r, k);
        else return quickSelect(arr, l, pivot - 1, k);
    }

    static int partition(int[] arr, int l, int r) {
        int pivot = arr[r];
        int i = l;

        for (int j = l; j < r; j++) {
            if (arr[j] <= pivot) {
                swap(arr, i++, j);
            }
        }
        swap(arr, i, r);
        return i;
    }

    static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }
}
```

