        int low = 0, high = arr.length - 1, i = 0;

        while (i <= high) {
            if (arr[i] < pivot) {
                swap(arr, i++, low++);
            } else if (arr[i] > pivot) {
                swap(arr, i, high--);
            } else {
                i++;
            }
        }
    }

