    static void quickSort(int[] arr, int l, int r) {
        if (l >= r) return;

        int pi = partition(arr, l, r);

        quickSort(arr, l, pi - 1);
        quickSort(arr, pi + 1, r);
    }

    static int partition(int[] arr, int l, int r) {
        int pivot = arr[r], i = l;

        for (int j = l; j < r; j++) {
            if (arr[j] <= pivot) {
                int t = arr[i];
                arr[i++] = arr[j];
                arr[j] = t;
            }
        }

        int t = arr[i];
        arr[i] = arr[r];
        arr[r] = t;

        return i;
    }
}
