### 2. Using Single Temp Array (Optimized 🔥)

```java id="ci2p7m"
import java.util.*;

public class CountInversions {

    public static void main(String[] args) {
        int[] arr = {2,4,1,3,5};
        int[] temp = new int[arr.length];

        System.out.println(mergeSort(arr, temp, 0, arr.length - 1));
    }

    static int mergeSort(int[] arr, int[] temp, int l, int r) {
        int count = 0;

        if (l < r) {
            int mid = (l + r) / 2;

            count += mergeSort(arr, temp, l, mid);
            count += mergeSort(arr, temp, mid + 1, r);
            count += merge(arr, temp, l, mid, r);
        }

        return count;
    }

    static int merge(int[] arr, int[] temp, int l, int m, int r) {
        int i = l, j = m + 1, k = l, count = 0;

        while (i <= m && j <= r) {
            if (arr[i] <= arr[j]) temp[k++] = arr[i++];
            else {
                temp[k++] = arr[j++];
                count += (m - i + 1);
            }
        }

        while (i <= m) temp[k++] = arr[i++];
        while (j <= r) temp[k++] = arr[j++];

        for (int x = l; x <= r; x++) arr[x] = temp[x];

        return count;
    }
}
```

