### 2. Dynamic Stack (Auto Resize 🔥🔥)

```java id="stka2"
import java.util.*;

public class StackArray {
    int[] arr;
    int top;

    StackArray() {
        arr = new int[2];
        top = -1;
    }

    void push(int x) {
        if (top == arr.length - 1) resize();
        arr[++top] = x;
    }

    int pop() {
        if (top == -1) throw new RuntimeException("Empty stack");
        return arr[top--];
    }

    int peek() {
        if (top == -1) throw new RuntimeException("Empty stack");
        return arr[top];
    }

    void resize() {
        arr = Arrays.copyOf(arr, arr.length * 2);
    }

    public static void main(String[] args) {
        StackArray s = new StackArray();

        s.push(1);
        s.push(2);
        s.push(3); // triggers resize

        System.out.println(s.pop());
    }
}
```

