### 3. Generic Priority Queue 🔥

```java id="pq3"
import java.util.*;

public class PriorityQueueCustom<T> {
    ArrayList<T> heap = new ArrayList<>();
    Comparator<T> comp;

    PriorityQueueCustom(Comparator<T> comp) {
        this.comp = comp;
    }

    void add(T val) {
        heap.add(val);
        int i = heap.size() - 1;

        while (i > 0 && comp.compare(heap.get(i), heap.get(parent(i))) < 0) {
            swap(i, parent(i));
            i = parent(i);
        }
    }

    T poll() {
        if (heap.isEmpty()) throw new RuntimeException("Empty");

        T root = heap.get(0);
        heap.set(0, heap.remove(heap.size() - 1));

        heapify(0);
        return root;
    }

    void heapify(int i) {
        int smallest = i;
        int l = left(i), r = right(i);

        if (l < heap.size() && comp.compare(heap.get(l), heap.get(smallest)) < 0)
            smallest = l;

        if (r < heap.size() && comp.compare(heap.get(r), heap.get(smallest)) < 0)
            smallest = r;

        if (smallest != i) {
            swap(i, smallest);
            heapify(smallest);
        }
    }

    int parent(int i) { return (i - 1) / 2; }
    int left(int i) { return 2*i + 1; }
    int right(int i) { return 2*i + 2; }

    void swap(int i, int j) {
        T t = heap.get(i);
        heap.set(i, heap.get(j));
        heap.set(j, t);
    }
}
