import java.util.*;

public class BuildHeap {
    int[] heap;
    int size;

    BuildHeap(int[] arr) {
        heap = arr;
        size = arr.length;

        for (int i = size/2 - 1; i >= 0; i--) {
            heapify(i);
        }
    }

    void heapify(int i) {
        int smallest = i;
        int l = 2*i+1, r = 2*i+2;

        if (l < size && heap[l] < heap[smallest]) smallest = l;
        if (r < size && heap[r] < heap[smallest]) smallest = r;

        if (smallest != i) {
            int t = heap[i];
            heap[i] = heap[smallest];
