### 5. Thread-Safe Version

```java id="pq5"
public class MinHeap {
    int[] heap;
    int size;

    MinHeap(int cap) {
        heap = new int[cap];
    }

    synchronized void insert(int val) {
        heap[size] = val;
        int i = size++;

        while (i > 0 && heap[(i-1)/2] > heap[i]) {
            int t = heap[i];
            heap[i] = heap[(i-1)/2];
            heap[(i-1)/2] = t;
            i = (i-1)/2;
        }
    }

    synchronized int extractMin() {
        if (size == 0) return -1;

        int root = heap[0];
        heap[0] = heap[--size];

        heapify(0);
        return root;
    }

    void heapify(int i) {
        int smallest = i, l = 2*i+1, r = 2*i+2;

        if (l < size && heap[l] < heap[smallest]) smallest = l;
        if (r < size && heap[r] < heap[smallest]) smallest = r;

        if (smallest != i) {
            int t = heap[i];
            heap[i] = heap[smallest];
            heap[smallest] = t;
            heapify(smallest);
        }
    }
}
```

