public class ReverseLL {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static Node reverseBetween(Node head, int m, int n) {
        if (head == null) return null;

        Node dummy = new Node(0);
        dummy.next = head;

        Node prev = dummy;

        for (int i = 1; i < m; i++) {
            prev = prev.next;
        }

        Node curr = prev.next;

        for (int i = 0; i < n - m; i++) {
            Node next = curr.next;
            curr.next = next.next;
            next.next = prev.next;
            prev.next = next;
        }

        return dummy.next;
    }
}
