### 4. Reverse in K Groups 🔥🔥

```java id="rll4"
public class ReverseLL {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static Node reverseKGroup(Node head, int k) {
        Node curr = head;
        int count = 0;

        while (curr != null && count < k) {
            curr = curr.next;
            count++;
        }

        if (count == k) {
            curr = reverseKGroup(curr, k);

            while (count-- > 0) {
                Node next = head.next;
                head.next = curr;
                curr = head;
                head = next;
            }
            head = curr;
        }

        return head;
    }
}
