    while (l1 != null && l2 != null) {
        Node prev = null;

        while (l1 != null && l1.val <= l2.val) {
            prev = l1;
            l1 = l1.next;
        }

        prev.next = l2;

        Node temp = l1;
        l1 = l2;
        l2 = temp;
    }

    return res;
}
