### 1. Reverse Second Half (Most Important 🔥 O(n), O(1))

```java id="pl1"
public class PalindromeLL {

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }

    static boolean isPalindrome(Node head) {
        if (head == null || head.next == null) return true;

        // find middle
        Node slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // reverse second half
        Node prev = null, curr = slow;
        while (curr != null) {
            Node next = curr.next;
            curr.next = prev;
            prev = curr;
            curr = next;
        }

        // compare both halves
        Node p1 = head, p2 = prev;
        while (p2 != null) {
            if (p1.val != p2.val) return false;
            p1 = p1.next;
            p2 = p2.next;
        }

        return true;
    }
}
```

