    Node temp = a;
    while (temp.next != null) temp = temp.next;

    temp.next = b; // make cycle

    Node slow = a, fast = a;

    while (fast != null && fast.next != null) {
        slow = slow.next;
        fast = fast.next.next;

        if (slow == fast) break;
