### 1. Optimal (O(1) Space - Most Important 🔥🔥)

```java id="cl1"
public class CloneList {

    static class Node {
        int val;
        Node next, random;

        Node(int v) { val = v; }
    }

    static Node copyRandomList(Node head) {
        if (head == null) return null;

        // 1. Insert copy nodes
        Node curr = head;
        while (curr != null) {
            Node copy = new Node(curr.val);
            copy.next = curr.next;
            curr.next = copy;
            curr = copy.next;
        }

        // 2. Assign random pointers
        curr = head;
        while (curr != null) {
            if (curr.random != null) {
                curr.next.random = curr.random.next;
            }
            curr = curr.next.next;
        }

        // 3. Separate lists
        curr = head;
        Node dummy = new Node(0);
        Node copyCurr = dummy;

        while (curr != null) {
            Node copy = curr.next;

            copyCurr.next = copy;
            copyCurr = copy;

            curr.next = copy.next;
            curr = curr.next;
        }

        return dummy.next;
    }
}
```

