### 2. Bottom-Up Merge Sort (Iterative 🔥)

```java id="llms2"
public class SortLinkedList {

    static Node sortList(Node head) {
        if (head == null) return null;

        int len = getLength(head);
        Node dummy = new Node(0);
        dummy.next = head;

        for (int size = 1; size < len; size *= 2) {
            Node curr = dummy.next, tail = dummy;

            while (curr != null) {
                Node left = curr;
                Node right = split(left, size);
                curr = split(right, size);

                tail.next = merge(left, right);

                while (tail.next != null) tail = tail.next;
            }
        }

        return dummy.next;
    }

    static int getLength(Node head) {
        int len = 0;
        while (head != null) {
            len++;
            head = head.next;
        }
        return len;
    }

    static Node split(Node head, int size) {
        for (int i = 1; head != null && i < size; i++) {
            head = head.next;
        }

        if (head == null) return null;

        Node next = head.next;
        head.next = null;
        return next;
    }

    static Node merge(Node a, Node b) {
        Node dummy = new Node(0), curr = dummy;

        while (a != null && b != null) {
            if (a.val <= b.val) {
                curr.next = a;
                a = a.next;
            } else {
                curr.next = b;
                b = b.next;
            }
            curr = curr.next;
        }

        curr.next = (a != null) ? a : b;
        return dummy.next;
    }

    static class Node {
        int val;
        Node next;
        Node(int v) { val = v; }
    }
}
