import java.util.*;

static int height(Node root) {
    if (root == null) return 0;

    Stack<Pair> stack = new Stack<>();
    stack.push(new Pair(root, 1));

    int max = 0;

    while (!stack.isEmpty()) {
        Pair p = stack.pop();
        Node node = p.node;
        int depth = p.depth;

        max = Math.max(max, depth);

        if (node.left != null)
            stack.push(new Pair(node.left, depth + 1));

        if (node.right != null)
            stack.push(new Pair(node.right, depth + 1));
    }

    return max;
}

static class Pair {
    Node node;
    int depth;
    Pair(Node n, int d) { node = n; depth = d; }
}
