static boolean isValidBST(Node root) {
    Stack<Node> stack = new Stack<>();
    Node curr = root;
    Integer prev = null;

    while (curr != null || !stack.isEmpty()) {
        while (curr != null) {
            stack.push(curr);
            curr = curr.left;
