### 2. Return Height + Diameter Together 🔥

```java id="dia2"
class Pair {
    int height, diameter;

    Pair(int h, int d) {
        height = h;
        diameter = d;
    }
}

static Pair solve(Node root) {
    if (root == null) return new Pair(0, 0);

    Pair left = solve(root.left);
    Pair right = solve(root.right);

    int height = 1 + Math.max(left.height, right.height);

    int diaThroughRoot = left.height + right.height;
    int diameter = Math.max(diaThroughRoot,
                     Math.max(left.diameter, right.diameter));

    return new Pair(height, diameter);
}
