import java.util.*;

static List<Integer> shortestPath(int V, List<List<Pair>> adj, int src, int dest) {
    int[] dist = new int[V];
    int[] parent = new int[V];

    Arrays.fill(dist, Integer.MAX_VALUE);
    for (int i = 0; i < V; i++) parent[i] = i;

    PriorityQueue<Pair> pq = new PriorityQueue<>((a,b)->a.dist-b.dist);

    dist[src] = 0;
    pq.offer(new Pair(src, 0));

    while (!pq.isEmpty()) {
        Pair curr = pq.poll();

        for (Pair nei : adj.get(curr.node)) {
            if (dist[curr.node] + nei.dist < dist[nei.node]) {
                dist[nei.node] = dist[curr.node] + nei.dist;
                parent[nei.node] = curr.node;
                pq.offer(new Pair(nei.node, dist[nei.node]));
            }
        }
    }

    List<Integer> path = new ArrayList<>();
    int node = dest;

    while (parent[node] != node) {
        path.add(node);
        node = parent[node];
    }
    path.add(src);

    Collections.reverse(path);
    return path;
}
