### 1. DFS Based Topological Sort 🔥 (Stack)

```java id="topo1"
import java.util.*;

public class TopoSortDFS {

    static void dfs(int node, boolean[] visited,
                    Stack<Integer> stack, List<List<Integer>> adj) {

        visited[node] = true;

        for (int nei : adj.get(node)) {
            if (!visited[nei]) {
                dfs(nei, visited, stack, adj);
            }
        }

        stack.push(node); // post-order
    }

    static List<Integer> topoSort(int V, List<List<Integer>> adj) {
        boolean[] visited = new boolean[V];
        Stack<Integer> stack = new Stack<>();

        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                dfs(i, visited, stack, adj);
            }
        }

        List<Integer> res = new ArrayList<>();
        while (!stack.isEmpty()) {
            res.add(stack.pop());
        }

        return res;
    }
}
