### 3. Union-Find (Disjoint Set 🔥🔥)

```java id="cc3"
class DSU {
    int[] parent, rank;

    DSU(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void union(int a, int b) {
        int pa = find(a), pb = find(b);

        if (pa == pb) return;

        if (rank[pa] < rank[pb]) {
            parent[pa] = pb;
        } else if (rank[pa] > rank[pb]) {
            parent[pb] = pa;
        } else {
            parent[pb] = pa;
            rank[pa]++;
        }
    }
}

static int countComponents(int V, int[][] edges) {
    DSU dsu = new DSU(V);

    for (int[] e : edges) {
        dsu.union(e[0], e[1]);
    }

    Set<Integer> set = new HashSet<>();

    for (int i = 0; i < V; i++) {
        set.add(dsu.find(i));
    }

    return set.size();
}
```

