### 5. Leaky Bucket 🔥

```java id="rl5"
import java.util.*;

class LeakyBucket {
    private final int capacity;
    private final long leakInterval;

    private Queue<Long> queue = new LinkedList<>();

    LeakyBucket(int capacity, long leakIntervalMs) {
        this.capacity = capacity;
        this.leakInterval = leakIntervalMs;
    }

    public synchronized boolean allow() {
        long now = System.currentTimeMillis();

        while (!queue.isEmpty() &&
               now - queue.peek() >= leakInterval) {
            queue.poll();
        }

        if (queue.size() < capacity) {
            queue.offer(now);
            return true;
        }

        return false;
    }
}
```

