    public <T> Future<T> debounce(Callable<T> task, long delayMs) {
        if (future != null && !future.isDone()) {
            future.cancel(false);
        }

        return (Future<T>) scheduler.schedule(task, delayMs, TimeUnit.MILLISECONDS);
    }
}
