### 5. Async Retry (ScheduledExecutor 🔥🔥)

```java id="rb5"
import java.util.concurrent.*;

public class RetryAsync {

    static ScheduledExecutorService scheduler =
            Executors.newScheduledThreadPool(1);

    public static <T> CompletableFuture<T> retryAsync(
            Callable<T> task, int maxAttempts, long delay) {

        CompletableFuture<T> future = new CompletableFuture<>();
        attempt(task, maxAttempts, delay, future);
        return future;
    }

    private static <T> void attempt(Callable<T> task,
                                   int attempts,
                                   long delay,
                                   CompletableFuture<T> future) {

        scheduler.schedule(() -> {
            try {
                future.complete(task.call());
            } catch (Exception e) {
                if (attempts <= 1) {
                    future.completeExceptionally(e);
                } else {
                    attempt(task, attempts - 1, delay * 2, future);
                }
            }
        }, delay, TimeUnit.MILLISECONDS);
    }
}
```

