import java.util.*;

class UrlShortener {

    private static final String BASE62 =
            "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    private Map<String, String> map = new HashMap<>();
    private Random rand = new Random();

