            key = generateKey(6);
        } while (map.containsKey(key));

        map.put(key, longUrl);
        return "http://short.ly/" + key;
    }

    public String decode(String shortUrl) {
        String key = shortUrl.substring(shortUrl.lastIndexOf("/") + 1);
        return map.get(key);
    }

    private String generateKey(int len) {
        StringBuilder sb = new StringBuilder();

        for (int i = 0; i < len; i++) {
            sb.append(BASE62.charAt(rand.nextInt(62)));
        }

        return sb.toString();
    }
}
